<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';const username=ref('developer');const busy=ref(false);const auth=useAuthStore();const router=useRouter();async function login(){busy.value=true;try{await auth.login(username.value);await router.push('/app/home')}finally{busy.value=false}}</script><template><v-app><v-main id="main"><v-container class="login"><v-card max-width="480"><v-card-title>Sign in</v-card-title><v-card-text><v-text-field v-model="username" label="Development identity" autocomplete="username"/></v-card-text><v-card-actions><v-btn color="primary" :loading="busy" @click="login">Development login</v-btn></v-card-actions></v-card></v-container></v-main></v-app></template>
